const BIRTH_ERAS=[{"year":500,"name":"ยุคตั้งหลักหลังเถ้าดำ","intro":"บ้านเมืองเพิ่งฟื้นจากความพังพินาศ หลายครอบครัวอาศัยใกล้แหล่งน้ำและช่วยกันซ่อมสิ่งที่เหลืออยู่ ชื่อสกุลส่วนใหญ่ยังไม่ได้หมายถึงอำนาจ","learning":"เด็กเรียนจากคนในบ้าน ผู้เฒ่า และช่างใกล้ตัว ยังไม่มีโรงเรียนชุมชนให้พบทั่วไป","work":"งานหาอาหาร เพาะปลูก ซ่อมเครื่องมือ และคุ้มกันทางใกล้บ้านสำคัญกว่างานในองค์กรใหญ่","tension":"อาหารขาดช่วง ถนนชำรุด และสิทธิใช้แหล่งน้ำอาจทำให้เพื่อนบ้านผิดใจกัน","native":"แหล่งน้ำและเขตหาอาหารเริ่มทับกับชุมชนที่กลับมาตั้งถิ่น คุณอาจต้องย้ายถิ่น ปกป้องรัง หรือยอมแบ่งพื้นที่"},{"year":800,"name":"ยุคเมืองท่าและเรือนใหญ่","intro":"เมืองเริ่มเชื่อมกันด้วยคาราวานและเรือ สกุลพ่อค้า ช่าง และเจ้าที่ดินมีบทบาทมากขึ้น แต่การเกิดในบ้านมีชื่อก็ยังไม่ได้รับประกันว่าจะได้ครองตำแหน่ง","learning":"มีครูในชุมชนและที่ฝึกงานเพิ่มขึ้น สำนักวิชาส่วนใหญ่ยังรับผ่านคนรู้จักหรือการฝากตัว","work":"การค้า งานช่าง การแปลภาษา และการเดินทางเปิดโอกาสใหม่ พร้อมค่าผ่านทางและเงื่อนไขของกิลด์","tension":"บางบ้านยังตั้งตัวหลังโรคระบาด คู่ค้าต้องเลือกระหว่างกำไรกับความไว้ใจ","native":"เรือ คาราวาน และเหมืองขยายเข้าใกล้ถิ่นเดิมของคุณ การหลบผู้คนหรือเจรจาเรื่องเขตแดนมีผลต่อการอยู่รอด"},{"year":1000,"name":"ยุคอาณาจักรและชายแดน","intro":"นี่คือยุคปัจจุบันของโลก ราชสำนัก กิลด์ และสำนักเวทมีอำนาจชัดเจน คุณอาจใช้ชีวิตธรรมดา รับหน้าที่ของตระกูล หรือออกเดินทางไปไกลกว่าบ้านเกิด","learning":"เรียนในชุมชน ฝึกกับช่าง หรือสอบเข้าสำนักวิชาได้ ฐานะและเวลาของครอบครัวยังเป็นข้อจำกัด","work":"มีทั้งงานในเมือง อาชีพเวท การทูต และงานนักผจญภัยข้ามอาณาจักร","tension":"ข่าวชายแดน ความขัดแย้งระหว่างเผ่า และการแย่งสิทธิสืบทอดอาจเข้ามาเปลี่ยนชีวิต","native":"อาณาจักรเริ่มกำหนดเขตป่า ทะเล และเส้นทางบิน คุณเลือกอยู่ห่าง ต่อรอง หรือเข้าร่วมกับสังคมอื่นได้"},{"year":1500,"name":"ยุคโรงเรียนและกฎบัตรใหม่","intro":"ความรู้เริ่มออกจากเรือนใหญ่ เมืองตั้งโรงเรียนและรับรองวิชาชีพร่วมกัน คนธรรมดามีช่องทางมากขึ้น แต่ค่าเรียน ค่าเช่า และเส้นสายยังทำให้แต่ละคนเริ่มต้นไม่เท่ากัน","learning":"มีตำรา ห้องเรียน และการเรียนต่อภาคค่ำให้เข้าถึงมากขึ้น การเรียนต่อยังต้องแลกกับเงินและเวลาทำงาน","work":"งานสอน วิจัย เครื่องกลเวท และวิชาชีพที่ใช้ใบรับรองขยายตัว งานฝีมือและเกษตรยังเลี้ยงผู้คนจำนวนมาก","tension":"สิทธิของโกเลมและผู้ตื่นรู้ อำนาจเก่าของตระกูล และค่าใช้จ่ายในเมืองเป็นเรื่องที่คนถกเถียงกัน","native":"ถนนและแหล่งพลังรุกใกล้รังเดิม ขณะบางเมืองยอมรับสิทธิของสิ่งมีชีวิตมากขึ้น คุณยังเป็นผู้เลือกว่าจะอยู่ร่วมกับโลกใหม่นี้อย่างไร"}];
